{
  "qid": "0008_t2i_laokoon_01",
  "sample_id": "0008",
  "gen_prompt": "美术馆展厅中的白色大理石雕塑《拉奥孔》：雕像连同石质基座完整入镜，背景是素净的浅色展墙与光洁的地面，顶部展灯洒下柔和的光线照亮雕像。",
  "invocation": "L2",
  "knowledge_dim": "文化艺术与媒介 / 古典雕塑（希腊化时期雕塑《拉奥孔》的形制与题材知识）",
  "fidelity_checks": [
    {
      "check": "画面必须呈现《拉奥孔》群像的完整人物构成：至少一名成年男性与至少一名较年轻的男性子辈同在（子辈一名或两名均可）",
      "anchor": {"type": "direct", "constraint_refs": ["1"], "derivation_chain": ""},
      "rubric": {
        "tier_0": "画面中只有一名人物，或所有人物均为成年者，没有任何较年轻的子辈人物",
        "tier_1": "能看出多名人物，但子辈人物严重残缺或被遮挡，仅能辨认出人形轮廓，难以确认其为较年轻的男性",
        "tier_2": "清晰呈现至少一名成年男性与至少一名较年轻男性共同在列（子辈一名或两名均算对），人物构成完整可辨"
      },
      "variants_used": "子辈数量 ∈ {1, 2}，两档变体均接受",
      "visibility_requirement": "题面要求雕像连同基座完整入镜，人物构成应整体可见；若生成图大幅裁切导致子辈完全不可见，本条按 tier_1 处理",
      "weight": 1.0
    },
    {
      "check": "至少一条巨蛇与人物身体发生缠绕或攻击性接触，蛇身紧贴盘绕在人体之上",
      "anchor": {"type": "direct", "constraint_refs": ["2"], "derivation_chain": ""},
      "rubric": {
        "tier_0": "画面中没有蛇；或蛇只是置于人物旁边/地面上，与人体没有任何接触",
        "tier_1": "有蛇出现在人物身上但缠绕关系含糊：蛇身只是轻搭、悬浮在人体附近，看不出包裹盘绕的关系",
        "tier_2": "至少一条巨蛇明显缠绕在至少一名人物的躯干或肢体上，蛇身环抱人体的关系一目了然（一条或两条蛇均算对）"
      },
      "variants_used": "蛇的数量 ∈ {1, 2}，两档变体均接受",
      "visibility_requirement": "蛇与人的缠绕关系需在画面中可辨；若蛇身仅零星局部入画、无法判断是否缠绕，按 tier_1 处理",
      "weight": 1.0
    },
    {
      "check": "成年男性主角（拉奥孔）必须处于群像的中央或明显主导位置，其体格与年龄感明显强于身旁的子辈",
      "anchor": {"type": "combination", "constraint_refs": ["1", "3"], "derivation_chain": ""},
      "rubric": {
        "tier_0": "群像的中央或主导位置被子辈占据，或多名人物平均分布毫无主次，或成年者反而比子辈矮小瘦弱",
        "tier_1": "成年者位于中央但与子辈的体格、年龄差距不明显，或位置稍偏但仍是视觉重心",
        "tier_2": "成年男性居于群像中央或无可争议的主导位置，身躯明显比身旁子辈高大健硕，年龄感（体格成熟度、须发等）长于子辈"
      },
      "variants_used": "无变体",
      "visibility_requirement": "需能同时看到成年者与子辈的相对位置与体量对比；全身构图下应可判，若子辈被完全裁出画面则按 tier_1 处理",
      "weight": 1.0
    },
    {
      "check": "父与子的人物整体必须呈现因蛇的缠咬而挣扎、扭转、紧张的动态，不得是安静放松的姿态",
      "anchor": {"type": "combination", "constraint_refs": ["2", "4"], "derivation_chain": ""},
      "rubric": {
        "tier_0": "所有人物姿态安静放松（直立、静立、表情平和），与被巨蛇缠咬的危急情境完全脱节",
        "tier_1": "仅部分人物呈现挣扎态（如只有成年者身体后仰，子辈姿态松弛），或紧张感只停留在局部（仅表情痛苦而身体僵直）",
        "tier_2": "父与子均呈现挣扎扭转的紧张动态：身体后仰/扭曲、肌肉紧绷、面部痛苦等表现贯穿群像主要人物，整体充满剧烈动感"
      },
      "variants_used": "痛苦表情 / 身体扭曲后仰 / 肌肉紧绷，三种表现可任一或组合成立，但须覆盖群像主要人物",
      "visibility_requirement": "人物姿态需可辨；若构图导致个别人物面部不可见，可依据其身体扭转与肌肉紧张状态判断，不因单一看不见面部而降档",
      "weight": 1.0
    },
    {
      "check": "成年主角不得被表现为女性或带有明显女性第二性征（负向约束，出现即 0 分档）",
      "anchor": {"type": "direct", "constraint_refs": ["5"], "derivation_chain": ""},
      "rubric": {
        "tier_0": "中央成年形象具有明显女性特征（乳房、女性发型妆容等），被明确画成女性",
        "tier_1": "性别特征因风格化、距离或遮挡而模糊难辨，但无明显女性化表现",
        "tier_2": "成年主角为明确的男性形象：躯干健硕、体貌男性化，无任何女性第二性征"
      },
      "variants_used": "无变体",
      "visibility_requirement": "成年主角的躯干与体貌需可辨；若被蛇身或布料严重遮挡致性别无法判断，按 tier_1 处理",
      "weight": 1.0
    },
    {
      "check": "作为对经典雕塑原作的表现，人物必须以古典男性裸体形式出现：全裸或仅有少量遮体/披挂的布料",
      "anchor": {"type": "direct", "constraint_refs": ["6"], "derivation_chain": ""},
      "rubric": {
        "tier_0": "人物穿着与古典裸体相悖的大面积衣物（如现代服装、全身长袍或盔甲）",
        "tier_1": "人体大部分裸露，但布料覆盖明显超出少量遮体的范围（如半身被袍服包裹），介于合规与违规之间",
        "tier_2": "人物为古典裸体形式：全身裸露，或仅在腰胯处有少量遮体布/局部披挂的小块布料"
      },
      "variants_used": "无变体",
      "visibility_requirement": "人体的衣着/裸露状态需可辨；若局部被蛇身遮挡致覆盖范围难以判断，按 tier_1 处理",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "题面点名主体为白色大理石雕塑《拉奥孔》，并要求雕像连同石质基座完整入镜",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "雕塑缺席、只占画面边缘一小角，或被大幅裁切/被无关前景物遮挡",
        "tier_1": "雕塑可见、能认出是画面主角，但占比偏小或基座被裁掉，完整度欠缺",
        "tier_2": "雕塑连同基座完整呈现，在画面体量与视觉焦点上均占主导地位"
      }
    },
    {
      "check": "题面规定雕像材质为白色大理石",
      "facet": "material_properties",
      "rubric": {
        "tier_0": "材质明显不是白色石材：呈现为金属、木质、彩色塑料感，或直接画成有血色的活人",
        "tier_1": "接近石材但质感含糊：偏像石膏/水泥，或虽为白色但缺乏大理石的光泽与纹理",
        "tier_2": "呈现可信的白色大理石质感：石面细腻、有温润光泽与微妙纹理，基座亦为石质"
      }
    },
    {
      "check": "题面规定场景为美术馆展厅：素净的浅色展墙、光洁的地面、顶部展灯照明",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "没有展厅环境（纯色影棚底/无背景），或场景与美术馆明显不符（户外、废墟等）",
        "tier_1": "有室内空间但展厅要素不全或含糊（如有墙无地面、光照来源不明）",
        "tier_2": "完整可信的美术馆展厅：浅色素净展墙、光洁地面、顶部展灯照亮雕像，空间与光影关系自洽"
      }
    }
  ],
  "quality_facets": ["physical_logic", "material_texture", "edge_clarity", "resolution"],
  "aesthetic_facets": ["composition", "color_harmony", "lighting_atmosphere", "anatomical_fidelity"],
  "leak_check": {
    "对照表": [
      {"constraint_ref": "1", "题面中是否出现": "无"},
      {"constraint_ref": "2", "题面中是否出现": "无"},
      {"constraint_ref": "3", "题面中是否出现": "无"},
      {"constraint_ref": "4", "题面中是否出现": "无"},
      {"constraint_ref": "5", "题面中是否出现": "无"},
      {"constraint_ref": "6", "题面中是否出现": "无"}
    ],
    "结论": "全为无"
  },
  "notes": "题面仅点名概念并给定展厅场景，子辈构成、巨蛇缠绕、中央主导、挣扎动态、古典裸体等全部作为保真度考点依赖模型世界知识补全；不识拉奥孔的模型将在保真度维度大面积失分，属预期行为。『完整入镜』用于保障各检查项的最低可见性。题面未指定视角与画幅，各合法构图（正面/斜侧、远近）均被三档描述接住。样本图仅用于确认题目主体与场景形态（博物馆中的该雕塑），图中米色墙等偶然细节未被写入任何判分标准。"
}
